/* Risograph Global Styles */

:root {
  --riso-pink: #ff6b9d;
  --riso-blue: #2563eb;
  --riso-orange: #ff8a00;
  --riso-green: #22c55e;
  --riso-paper: #fffbf0;
}

/* Grain texture overlay */
.riso-grain::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.08'/%3E%3C/svg%3E");
  pointer-events: none;
  mix-blend-mode: multiply;
}

/* Overprint offset */
.riso-offset {
  position: relative;
}
.riso-offset::after {
  content: attr(data-text);
  position: absolute;
  top: 2px;
  left: 3px;
  color: var(--riso-blue);
  opacity: 0.6;
  mix-blend-mode: multiply;
}

/* Halftone pattern */
.riso-halftone {
  background-image: radial-gradient(circle, currentColor 1px, transparent 1px);
  background-size: 4px 4px;
}
@keyframes risograph-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes risograph-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.risograph-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(255, 107, 157, 0.08);
}

.risograph-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.risograph-animate-in {
  animation: risograph-fade-in 0.5s ease-out both;
}

/* Mecha Global Styles */

:root {
  --mecha-navy: #1a2744;
  --mecha-green: #4a5c3a;
  --mecha-yellow: #fbbf24;
  --mecha-red: #ef4444;
}

/* Tech grid background */
.mecha-grid {
  background-image:
    linear-gradient(rgba(74, 92, 58, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(74, 92, 58, 0.15) 1px, transparent 1px);
  background-size: 40px 40px;
}

/* Warning stripe pattern */
.mecha-warning {
  background: repeating-linear-gradient(
    -45deg,
    var(--mecha-yellow),
    var(--mecha-yellow) 10px,
    var(--mecha-navy) 10px,
    var(--mecha-navy) 20px
  );
}

/* Panel border */
.mecha-panel {
  border: 2px solid var(--mecha-green);
  background: var(--mecha-navy);
  position: relative;
}
.mecha-panel::before {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  right: -4px;
  bottom: -4px;
  border: 1px solid rgba(251, 191, 36, 0.2);
  pointer-events: none;
}

/* Status indicator */
.mecha-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: monospace;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--mecha-green);
}
.mecha-status::before {
  content: "";
  width: 8px;
  height: 8px;
  background: var(--mecha-yellow);
}
@keyframes mecha-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes mecha-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.mecha-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(26, 39, 68, 0.08);
}

.mecha-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.mecha-animate-in {
  animation: mecha-fade-in 0.5s ease-out both;
}

/* Gothic Lolita 全局样式 */

:root {
  --gl-black: #0a0a0a;
  --gl-purple: #4a1a4a;
  --gl-red: #8b1a2a;
  --gl-silver: #e5e5e5;
}

/* 蕾丝花边装饰 */
.gl-lace-border {
  border-image: repeating-linear-gradient(
    90deg,
    var(--gl-purple) 0px,
    var(--gl-purple) 4px,
    transparent 4px,
    transparent 8px
  ) 1;
}

/* 哥特十字架装饰 */
.gl-cross::before {
  content: "+";
  font-size: 1.2em;
  color: var(--gl-red);
  margin-right: 0.5em;
}

/* 玫瑰阴影 */
.gl-rose-shadow {
  box-shadow:
    0 4px 16px rgba(139, 26, 42, 0.3),
    inset 0 1px 0 rgba(229, 229, 229, 0.1);
}

/* 暗色渐变 */
.gl-dark-gradient {
  background: linear-gradient(
    to bottom,
    #0a0a0a 0%,
    #1a0a1a 50%,
    #0a0a0a 100%
  );
}
@keyframes gothic-lolita-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes gothic-lolita-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.gothic-lolita-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(74, 26, 74, 0.08);
}

.gothic-lolita-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
