/* Acid Graphics Global Styles */

:root {
  --acid-green: #39ff14;
  --acid-black: #0a0a0a;
  --acid-yellow: #e6ff00;
  --acid-purple: #a020f0;
  --acid-pink: #ff6ec7;
  --acid-cyan: #00ffff;
}

/* Scanline overlay */
.acid-scanlines::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(57, 255, 20, 0.03) 2px,
    rgba(57, 255, 20, 0.03) 4px
  );
  pointer-events: none;
}

/* Op-Art checkerboard */
.acid-checkerboard {
  background-image:
    linear-gradient(45deg, rgba(57, 255, 20, 0.04) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(57, 255, 20, 0.04) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(57, 255, 20, 0.04) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(57, 255, 20, 0.04) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0;
}

/* Chrome text layering - use with data-text attribute */
.acid-chrome {
  position: relative;
}
.acid-chrome::before {
  content: attr(data-text);
  position: absolute;
  top: 2px;
  left: 3px;
  color: var(--acid-purple);
  opacity: 0.6;
}
.acid-chrome::after {
  content: attr(data-text);
  position: absolute;
  top: -2px;
  left: -2px;
  color: var(--acid-pink);
  opacity: 0.5;
}

/* Fluorescent glow */
.acid-glow {
  text-shadow: 0 0 10px var(--acid-green), 0 0 20px var(--acid-green), 0 0 40px var(--acid-green);
}

/* 3D wireframe grid */
.acid-wireframe-grid {
  background-image:
    linear-gradient(rgba(57, 255, 20, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(57, 255, 20, 0.08) 1px, transparent 1px);
  background-size: 40px 40px;
}

.acid-graphics-filter { filter: brightness(1.05) contrast(1.02); }

.acid-graphics-hover-lift { transition: transform 0.3s ease; }

.acid-graphics-hover-lift:hover { transform: translateY(-2px); }

/* Hand-Drawn Doodle Global Styles */

:root {
  --doodle-ink: #2c2c2c;
  --doodle-paper: #fffef5;
  --doodle-red: #ff6b6b;
  --doodle-teal: #4ecdc4;
  --doodle-yellow: #ffd93d;
}

/* Notebook lines background */
.doodle-lines {
  background-image: repeating-linear-gradient(
    transparent,
    transparent 31px,
    rgba(168, 200, 232, 0.35) 31px,
    rgba(168, 200, 232, 0.35) 32px
  );
}

/* Red margin line */
.doodle-margin::before {
  content: "";
  position: absolute;
  left: 120px;
  top: 0;
  bottom: 0;
  width: 1px;
  background-color: rgba(255, 107, 107, 0.2);
}

/* Squiggly underline */
.doodle-underline {
  text-decoration: underline;
  text-decoration-style: wavy;
  text-decoration-color: var(--doodle-red);
  text-underline-offset: 4px;
}

/* Marker highlight */
.doodle-highlight {
  background: linear-gradient(
    104deg,
    transparent 0.9%,
    rgba(255, 217, 61, 0.3) 2.4%,
    rgba(255, 217, 61, 0.2) 97.1%,
    transparent 98.2%
  );
  padding: 0 4px;
}

/* Tape decoration */
.doodle-tape {
  position: relative;
}
.doodle-tape::before {
  content: "";
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%) rotate(-3deg);
  width: 60px;
  height: 20px;
  background-color: rgba(255, 217, 61, 0.4);
  border-radius: 1px;
}

/* Sketchy rotation */
.doodle-tilt-left { transform: rotate(-1.5deg); }
.doodle-tilt-right { transform: rotate(1.5deg); }

/* Spiral binding holes */
.doodle-binding-holes::before {
  content: "";
  position: absolute;
  left: 50px;
  top: 0;
  bottom: 0;
  width: 16px;
  background-image: radial-gradient(circle, transparent 5px, transparent 5px),
    repeating-linear-gradient(
      transparent,
      transparent 60px,
      rgba(44, 44, 44, 0.08) 60px,
      rgba(44, 44, 44, 0.08) 76px,
      transparent 76px
    );
}

/* Swiss Poster Global Styles */

:root {
  --sp-black: #000000;
  --sp-white: #ffffff;
  --sp-red: #ff0000;
  --sp-blue: #0057b8;
  --sp-yellow: #ffcc00;
}

/* Structural grid overlay for development */
.sp-grid-overlay {
  background-image:
    linear-gradient(rgba(0, 0, 0, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.03) 1px, transparent 1px);
  background-size: calc(100% / 12) 100px;
}

/* Color block accents */
.sp-block-red { background-color: var(--sp-red); }
.sp-block-blue { background-color: var(--sp-blue); }
.sp-block-yellow { background-color: var(--sp-yellow); }

/* Tight tracking for poster headings */
.sp-tight { letter-spacing: -0.05em; }

/* Structural divider line */
.sp-divider {
  border: 2px solid var(--sp-black);
}

/* Vertical text for sidebar labels */
.sp-vertical-text {
  writing-mode: vertical-lr;
  transform: rotate(180deg);
  letter-spacing: 0.5em;
}

/* Asymmetric grid helper - 3/9 split */
.sp-grid-3-9 {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
}
.sp-grid-3-9 > :first-child { grid-column: span 3; }
.sp-grid-3-9 > :last-child { grid-column: span 9; }

/* Edge-to-edge buttons */
.sp-button-group {
  display: flex;
  gap: 0;
}
.sp-button-group > * + * {
  border: 0;
}
