/* Watercolor Art Global Styles */

:root {
  --wc-rose: #d4a0a0;
  --wc-paper: #faf6f0;
  --wc-cerulean: #7bb8d4;
  --wc-sage: #8cc5a8;
  --wc-lavender: #c3a0d4;
  --wc-ochre: #e8c87a;
  --wc-text: #5a3e3e;
}

/* Paper grain texture overlay */
.wc-paper::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='paper'%3E%3CfeTurbulence baseFrequency='0.5' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23paper)' opacity='0.03'/%3E%3C/svg%3E");
  pointer-events: none;
}

/* Watercolor wash section background */
.wc-wash {
  position: relative;
  overflow: hidden;
}
.wc-wash::before {
  content: "";
  position: absolute;
  inset: -20%;
  background: radial-gradient(ellipse at 30% 50%, var(--wc-rose) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 30%, var(--wc-cerulean) 0%, transparent 50%);
  opacity: 0.06;
  pointer-events: none;
}

/* Organic bleeding edge border radius */
.wc-bleed {
  border-radius: 40% 60% 50% 50% / 50% 40% 60% 50%;
}

/* Botanical accent decoration */
.wc-botanical::before {
  content: "";
  position: absolute;
  width: 40px;
  height: 40px;
  background: var(--wc-sage);
  opacity: 0.12;
  border-radius: 0 100% 0 100%;
  filter: blur(4px);
}
@keyframes watercolor-art-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes watercolor-art-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.watercolor-art-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(212, 160, 160, 0.08);
}

.watercolor-art-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.watercolor-art-animate-in {
  animation: watercolor-art-fade-in 0.5s ease-out both;
}

/* Impressionist Oil Global Styles */

:root {
  --imp-orange: #e8a87c;
  --imp-canvas: #f5f0e1;
  --imp-vermillion: #c0392b;
  --imp-blue: #2c3e50;
  --imp-turquoise: #1abc9c;
  --imp-gold: #f5d88a;
}

/* Canvas weave texture overlay */
.imp-canvas::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(44,62,80,0.03) 3px, transparent 4px),
    repeating-linear-gradient(90deg, transparent, transparent 3px, rgba(44,62,80,0.02) 3px, transparent 4px);
  opacity: 0.04;
  pointer-events: none;
}

/* Dappled light overlay - scattered radial gradient spots */
.imp-dapple::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle 80px at 20% 15%, rgba(245,216,138,0.08) 0%, transparent 100%),
    radial-gradient(circle 100px at 45% 10%, rgba(232,168,124,0.06) 0%, transparent 100%),
    radial-gradient(circle 70px at 75% 20%, rgba(245,216,138,0.07) 0%, transparent 100%),
    radial-gradient(circle 90px at 90% 60%, rgba(232,168,124,0.05) 0%, transparent 100%);
  pointer-events: none;
}

/* Brushstroke texture as repeating-linear-gradient */
.imp-brushstroke {
  background-image: repeating-linear-gradient(
    25deg,
    transparent,
    transparent 15px,
    rgba(232,168,124,0.02) 15px,
    transparent 16px
  );
}

/* Brushstroke underline decoration */
.imp-stroke {
  position: relative;
  display: inline-block;
}
.imp-stroke::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: -5%;
  width: 110%;
  height: 6px;
  background: var(--imp-orange);
  opacity: 0.5;
  border-radius: 50%;
  transform: rotate(-1deg);
}

/* Pointillism dot background */
.imp-dots {
  background-image:
    radial-gradient(circle, var(--imp-orange) 0.8px, transparent 0.8px),
    radial-gradient(circle, var(--imp-vermillion) 0.6px, transparent 0.6px);
  background-size: 12px 12px, 8px 8px;
  background-position: 0 0, 4px 4px;
  opacity: 0.06;
}

/* Immersive Photo Global Styles */

:root {
  --ip-ink: #0C0D10;
  --ip-paper: #F4F1EA;
  --ip-amber: #E8B04B;
  --ip-mist: #B8BCC4;
}

/* Ken Burns — transform only, compositor-friendly */
@keyframes ip-kenburns {
  from { transform: scale(1) translate3d(0, 0, 0); }
  to { transform: scale(1.12) translate3d(-2%, -1.5%, 0); }
}
.ip-kenburns {
  animation: ip-kenburns 18s ease-in-out infinite alternate;
  will-change: transform;
}

/* Full-bleed image base — always cover, explicit ratio at call site to avoid CLS */
.ip-cover {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Readability scrim presets */
.ip-scrim-bottom { background: linear-gradient(to top, rgba(0,0,0,0.72), rgba(0,0,0,0.15) 45%, transparent 70%); }
.ip-scrim-full { background: linear-gradient(to top, rgba(0,0,0,0.7), rgba(0,0,0,0.25) 50%, rgba(0,0,0,0.35)); }

/* Blur-up: LQIP is a scaled-up tiny image; real frame fades in on load */
.ip-lqip { filter: blur(16px); transform: scale(1.06); }
.ip-frame { opacity: 0; transition: opacity 0.8s ease; }
.ip-frame[data-loaded="true"] { opacity: 1; }

@media (prefers-reduced-motion: reduce) {
  .ip-kenburns { animation: none; }
  .ip-frame { transition: none; }
}

/* Collage Art Global Styles */

:root {
  --col-dark: #2d2d2d;
  --col-paper: #f5f0e8;
  --col-red: #e74c3c;
  --col-blue: #3498db;
  --col-yellow: #f39c12;
  --col-purple: #9b59b6;
}

/* Torn paper edge clip-path */
.col-torn {
  clip-path: polygon(
    0% 3%, 5% 0%, 12% 4%, 20% 1%, 28% 3%, 35% 0%, 42% 2%, 50% 0%,
    58% 3%, 65% 1%, 72% 4%, 80% 0%, 88% 2%, 95% 0%, 100% 3%,
    100% 97%, 95% 100%, 88% 98%, 80% 100%, 72% 97%, 65% 100%,
    58% 98%, 50% 100%, 42% 97%, 35% 100%, 28% 98%, 20% 100%,
    12% 97%, 5% 100%, 0% 98%
  );
}

/* Washi tape decoration - striped repeating-linear-gradient */
.col-tape {
  position: relative;
}
.col-tape::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 20%;
  width: 80px;
  height: 20px;
  background: repeating-linear-gradient(
    90deg,
    var(--col-yellow) 0px,
    var(--col-yellow) 3px,
    rgba(255,255,255,0.3) 3px,
    rgba(255,255,255,0.3) 6px
  );
  opacity: 0.7;
  transform: rotate(2deg);
}

/* Paper lift — hover 时上浮，active 时按压 */
.col-paper-lift {
  transition: all 0.2s ease-out;
}

.col-paper-lift:hover {
  transform: translateY(-8px) scale(1.02) rotate(-1deg);
  box-shadow: 12px 12px 0 var(--col-red);
}

.col-paper-lift:active {
  transform: translateY(2px) scale(0.98) rotate(1deg);
  box-shadow: 2px 2px 0 var(--col-red);
}

/* Stamp/postal mark decoration */
.col-stamp {
  border: 3px dashed var(--col-dark);
  padding: 8px;
  position: relative;
}
.col-stamp::after {
  content: "APPROVED";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(12deg);
  font-family: 'Courier New', monospace;
  font-size: 12px;
  font-weight: 700;
  color: var(--col-red);
  opacity: 0.3;
}

/* Newspaper column text */
.col-newspaper {
  font-family: 'Times New Roman', serif;
  line-height: 1.2;
  columns: 2;
  column-gap: 20px;
  column-rule: 1px solid var(--col-dark);
}

