/* Neon Samurai Global Styles */

:root {
  --ns-red: #dc2626;
  --ns-dark: #080818;
  --ns-purple: #a020f0;
  --ns-blue: #38bdf8;
  --ns-gold: #fbbf24;
}

/* Dual-color neon text glow (red text, blue glow) */
.ns-dual-glow {
  text-shadow: 0 0 20px var(--ns-blue), 0 0 40px rgba(56, 189, 248, 0.3);
  color: var(--ns-red);
}

/* Katana slash diagonal line */
.ns-slash-line {
  position: relative;
}
.ns-slash-line::after {
  content: "";
  position: absolute;
  top: 50%;
  left: -10%;
  right: -10%;
  height: 2px;
  background: linear-gradient(135deg, transparent 10%, var(--ns-red) 30%, var(--ns-red) 70%, transparent 90%);
  box-shadow: 0 0 12px var(--ns-blue);
  transform: rotate(-15deg);
  pointer-events: none;
}

/* Torii gate frame */
.ns-torii-frame {
  border: 3px solid var(--ns-red);
  border: 2px solid var(--ns-red);
  border: 2px solid var(--ns-red);
  box-shadow: 0 -4px 15px rgba(220, 38, 38, 0.3);
  position: relative;
}
.ns-torii-frame::before {
  content: "";
  position: absolute;
  top: 8px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--ns-red);
  opacity: 0.5;
}

/* Armor-plate clip path */
.ns-armor-clip {
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
}

/* Smoke overlay */
.ns-smoke::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 80%, rgba(220, 38, 38, 0.04) 0%, transparent 70%);
  pointer-events: none;
}

/* Scan line overlay */
.ns-scanlines::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.08) 2px,
    rgba(0, 0, 0, 0.08) 4px
  );
  pointer-events: none;
}

.neon-samurai-filter { filter: brightness(1.05) contrast(1.02); }

.neon-samurai-focus { outline: 2px solid var(--neon-samurai-primary, currentColor); outline-offset: 2px; }

/* Additional techniques */
@keyframes neon-samurai-shimmer { from { background-position: -200% 0; } to { background-position: 200% 0; } }

.neon-samurai-glass { backdrop-filter: blur(8px) saturate(150%); -webkit-backdrop-filter: blur(8px) saturate(150%); }

/* Magic Circle Global Styles */

:root {
  --mc-navy: #1e1b4b;
  --mc-dark: #0a0920;
  --mc-gold: #fbbf24;
  --mc-silver: #e2e8f0;
  --mc-indigo: #818cf8;
}

/* Golden glow text */
.mc-gold-glow {
  text-shadow: 0 0 25px var(--mc-gold), 0 0 50px rgba(251, 191, 36, 0.2);
}

/* Concentric ring decoration */
.mc-rings {
  position: relative;
}
.mc-rings::before {
  content: "";
  position: absolute;
  inset: -20px;
  border: 1px solid rgba(251, 191, 36, 0.08);
  border-radius: 50%;
  animation: mc-rotate 30s linear infinite;
}
.mc-rings::after {
  content: "";
  position: absolute;
  inset: -40px;
  border: 1px dashed rgba(129, 140, 248, 0.06);
  border-radius: 50%;
  animation: mc-rotate 45s linear infinite reverse;
}

@keyframes mc-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* Runic inscription border */
.mc-rune-border {
  position: relative;
}
.mc-rune-border::after {
  content: "--- ... --- . -- --- ...";
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 8px;
  letter-spacing: 4px;
  color: rgba(251, 191, 36, 0.15);
  pointer-events: none;
}

/* Sacred geometry shimmer */
.mc-sacred-bg {
  background-image:
    radial-gradient(circle at 50% 50%, rgba(251, 191, 36, 0.03) 0%, transparent 50%),
    radial-gradient(circle at 25% 25%, rgba(129, 140, 248, 0.02) 0%, transparent 40%),
    radial-gradient(circle at 75% 75%, rgba(129, 140, 248, 0.02) 0%, transparent 40%);
}

/* Center glow radiation */
.mc-center-glow {
  background: radial-gradient(
    circle at 50% 50%,
    rgba(251, 191, 36, 0.08) 0%,
    rgba(251, 191, 36, 0.02) 40%,
    transparent 70%
  );
}

/* Cyber Wafuu Global Styles */

:root {
  --cw-indigo: #1e3a5f;
  --cw-dark: #080814;
  --cw-vermillion: #c41e3a;
  --cw-gold: #c9a227;
  --cw-blue: #38bdf8;
}

/* Seigaiha wave pattern (digital version) */
.cw-seigaiha {
  background-image:
    radial-gradient(circle at 50% 100%, transparent 60%, rgba(56, 189, 248, 0.04) 60%, rgba(56, 189, 248, 0.04) 62%, transparent 62%),
    radial-gradient(circle at 0% 100%, transparent 60%, rgba(56, 189, 248, 0.04) 60%, rgba(56, 189, 248, 0.04) 62%, transparent 62%);
  background-size: 60px 30px;
}

/* Kintsugi gold crack line */
.cw-kintsugi {
  position: relative;
}
.cw-kintsugi::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 8px;
  right: 8px;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    var(--cw-gold) 15%,
    transparent 30%,
    var(--cw-gold) 50%,
    transparent 65%,
    var(--cw-gold) 80%,
    transparent 100%
  );
  opacity: 0.3;
  box-shadow: 0 0 6px rgba(201, 162, 39, 0.3);
}

/* Shoji screen grid */
.cw-shoji-grid {
  position: relative;
}
.cw-shoji-grid::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to right, rgba(30, 58, 95, 0.12) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(30, 58, 95, 0.12) 1px, transparent 1px);
  background-size: 33.33% 50%;
  pointer-events: none;
}

/* Circuit trace decoration */
.cw-circuit::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    var(--cw-blue) 15%,
    transparent 35%,
    var(--cw-blue) 55%,
    transparent 75%,
    var(--cw-blue) 90%,
    transparent 100%
  );
  opacity: 0.2;
}

/* Asanoha hemp leaf pattern overlay */
.cw-asanoha {
  background-image:
    linear-gradient(30deg, rgba(30, 58, 95, 0.06) 12%, transparent 12.5%, transparent 87%, rgba(30, 58, 95, 0.06) 87.5%),
    linear-gradient(150deg, rgba(30, 58, 95, 0.06) 12%, transparent 12.5%, transparent 87%, rgba(30, 58, 95, 0.06) 87.5%),
    linear-gradient(30deg, rgba(30, 58, 95, 0.06) 12%, transparent 12.5%, transparent 87%, rgba(30, 58, 95, 0.06) 87.5%),
    linear-gradient(150deg, rgba(30, 58, 95, 0.06) 12%, transparent 12.5%, transparent 87%, rgba(30, 58, 95, 0.06) 87.5%);
  background-size: 40px 70px;
  background-position: 0 0, 0 0, 20px 35px, 20px 35px;
}

/* Gold foil shimmer */
.cw-gold-foil {
  background: linear-gradient(
    135deg,
    rgba(201, 162, 39, 0.08) 0%,
    rgba(201, 162, 39, 0.03) 50%,
    rgba(201, 162, 39, 0.12) 100%
  );
}

.cyber-wafuu-filter { filter: brightness(1.05) contrast(1.02); }

.cyber-wafuu-hover-lift { transition: transform 0.3s ease; }

.cyber-wafuu-hover-lift:hover { transform: translateY(-2px); }

.cyber-wafuu-focus { outline: 2px solid var(--cyber-wafuu-primary, currentColor); outline-offset: 2px; }

